## Code Example

```typescript
interface IPolicy {
  apply(ctx: any, next: () => Promise<any>): Promise<any>;
}
class PolicyRegistry {
  private map = new Map<string, () => IPolicy>();
  register(name: string, factory: () => IPolicy) { this.map.set(name, factory); }
  get(name: string) { return this.map.get(name)!; }
}
class PolicyPipeline {
  constructor(private factories: Array<() => IPolicy>) {}
  async run(ctx: any, taskFn: () => Promise<any>) {
    let fn = taskFn;
    for (const factory of this.factories.reverse()) {
      const policy = factory();
      const next = fn;
      fn = () => policy.apply(ctx, next);
    }
    return fn();
  }
}
```

